package apigen

import (
	"fmt"
	"go/format"
	"strings"
)

// header heads every generated file, as its language comments.
const header = "Code generated by protoc-gen-makoplugin from proto/mako/plugin/v1. DO NOT EDIT."

// genGo writes the dispatcher: a method's name to its permission, checked
// first, then its request decoded and its handler called. A method has a
// case only through the schema, and every case checks the permission the
// schema gives it, so none can be reached unchecked.
func genGo(a *api) []byte {
	var b strings.Builder
	b.WriteString("// " + header + "\n\npackage hostapi\n\nimport \"context\"\n\n")

	perms := a.permissions()
	b.WriteString("// The permissions the Host API's methods take, as manifests name them;\n")
	b.WriteString("// PermNet stands for net:<host>, the host the call names.\nconst (\n")
	fmt.Fprintf(&b, "\tPermNone = %q\n", PermNone)
	for _, p := range perms {
		fmt.Fprintf(&b, "\t%s = %q\n", goPermName(p), p)
	}
	b.WriteString(")\n\n")
	b.WriteString("// Permissions are those a manifest may ask for, by the names above.\nvar Permissions = []string{")
	for i, p := range perms {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(goPermName(p))
	}
	b.WriteString("}\n\n")

	b.WriteString("// Handler carries out the Host API's methods that are available; Dispatch\n")
	b.WriteString("// calls one only once the caller's permission for it is checked.\ntype Handler interface {\n")
	for _, s := range a.services {
		for _, m := range s.methods {
			if m.unavailable {
				continue
			}
			fmt.Fprintf(&b, "\t// %s carries out %s.", s.short+m.name, m.key())
			if m.doc != "" {
				b.WriteString("\n")
				prefixed(&b, "\t", "// ", m.doc)
			} else {
				b.WriteString("\n")
			}
			fmt.Fprintf(&b, "\t%s%s(ctx context.Context, req *%s) (*%s, error)\n", s.short, m.name, m.in.name, m.out.name)
		}
	}
	b.WriteString("}\n\n")

	b.WriteString("// Methods are the Host API's methods, as the bindings name them, in the\n")
	b.WriteString("// schema's order.\nvar Methods = []Method{\n")
	for _, s := range a.services {
		for _, m := range s.methods {
			fmt.Fprintf(&b, "\t{Name: %q, Permission: %s", m.key(), permConst(m.perm))
			if m.unavailable {
				b.WriteString(", Unavailable: true")
			}
			b.WriteString("},\n")
		}
	}
	b.WriteString("}\n\n")

	b.WriteString("// Dispatch carries out the method called name with req, its request as\n")
	b.WriteString("// JSON, for a plugin that holds grants, and returns the response as JSON.\n")
	b.WriteString("// It refuses a method the plugin has no permission for before it reads\n// the request.\n")
	b.WriteString("func Dispatch(ctx context.Context, grants Grants, h Handler, name string, req []byte) ([]byte, error) {\n\tswitch name {\n")
	for _, s := range a.services {
		for _, m := range s.methods {
			fmt.Fprintf(&b, "\tcase %q:\n", m.key())
			if m.perm != PermNone {
				fmt.Fprintf(&b, "\t\tif !grants.Has(%s) {\n\t\t\treturn nil, &DeniedError{Method: name, Permission: %s}\n\t\t}\n", permConst(m.perm), permConst(m.perm))
			}
			if m.unavailable {
				b.WriteString("\t\treturn nil, &UnavailableError{Method: name}\n")
				continue
			}
			fmt.Fprintf(&b, "\t\treturn call(ctx, req, new(%s), h.%s%s)\n", m.in.name, s.short, m.name)
		}
	}
	b.WriteString("\t}\n\treturn nil, &UnknownError{Method: name}\n}\n")

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		panic(fmt.Sprintf("apigen: generated Go does not parse: %v\n%s", err, b.String()))
	}
	return out
}

func permConst(p string) string {
	if p == PermNone {
		return "PermNone"
	}
	return goPermName(p)
}
